CREATE TABLE IF NOT EXISTS money_nhso_dataset (hcode CHAR(5) NOT NULL, fy SMALLINT NOT NULL, name VARCHAR(255) NOT NULL, region VARCHAR(255) NOT NULL, date_from DATE NULL, date_to DATE NULL, file_name VARCHAR(255) NOT NULL, row_count INT NOT NULL, transfer_total DECIMAL(15,2) NOT NULL, rows_json LONGTEXT NOT NULL, uploaded_at DATETIME NOT NULL, uploaded_by CHAR(36) NOT NULL, PRIMARY KEY (hcode, fy), CONSTRAINT money_nhso_dataset_person_fk FOREIGN KEY (uploaded_by) REFERENCES person(id)) DEFAULT CHARSET=utf8mb4;
